```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology" ;
    rdfs:comment "Ontology modelling securities, debt, equity, hybrid and derivative instruments as described in the source corpus." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

fis:Asset a owl:Class ;
    rdfs:label "Asset" ;
    rdfs:comment "A generic resource (commodity, currency, index, interest rate benchmark or financial instrument) that can underlie a derivative or be owned." .

fis:FinancialInstrument a owl:Class ;
    rdfs:subClassOf fis:Asset ;
    rdfs:label "Financial Instrument" ;
    rdfs:comment "A monetary contract between parties; any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity (IAS 32)." .

fis:CashInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "Cash Instrument" ;
    rdfs:comment "Instrument whose value is determined directly by the markets; includes securities (readily transferable) and instruments such as loans and deposits (which require agreement to transfer)." .

fis:DerivativeInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "Derivative" , "Derivative Instrument" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:FinancialInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Asset ]
        )
    ] ;
    rdfs:comment "A contract whose value is derived from the performance of an underlier (asset, index, rate, or event). Every derivative has an underlier, a future act, a price, and a future date." .

fis:FinancialInstrument owl:equivalentClass [
    a owl:Class ;
    owl:unionOf ( fis:CashInstrument fis:DerivativeInstrument )
] .

fis:CashInstrument owl:disjointWith fis:DerivativeInstrument .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "Commodity" .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "Currency" .
fis:MarketIndex a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "Market Index" .
fis:InterestRateBenchmark a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "Interest Rate Benchmark" .

#################################################################
# SECURITY
#################################################################

fis:Security a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "Security" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:CashInstrument
            [ a owl:Restriction ; owl:onProperty fis:isTradable ; owl:hasValue true ]
        )
    ] ;
    rdfs:comment "A tradable financial asset. Note: the FCA Handbook and the first general passage of the corpus also classify stock options and warrants as 'securities', conflicting with the stricter US/IAS/BIS treatment of options as a distinct derivative category. This ontology follows the majority (cash-instrument vs derivative-instrument) treatment and records options/warrants as DerivativeInstrument rather than Security." .

fis:Loan a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "Loan" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:CashInstrument
            [ a owl:Restriction ; owl:onProperty fis:isTradable ; owl:hasValue false ]
        )
    ] ;
    rdfs:comment "A cash instrument requiring agreement of both borrower and lender for transfer; not a security." .

fis:Deposit a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "Deposit" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:CashInstrument
            [ a owl:Restriction ; owl:onProperty fis:isTradable ; owl:hasValue false ]
        )
    ] ;
    rdfs:comment "A cash instrument such as a bank deposit; not readily transferable without agreement." .

#################################################################
# CLAIM TYPES (differentiate debt vs equity)
#################################################################

fis:Claim a owl:Class ; rdfs:label "Claim" .
fis:ResidualClaim a owl:Class ; rdfs:subClassOf fis:Claim ; rdfs:label "Residual Claim" .
fis:CreditorClaim a owl:Class ; rdfs:subClassOf fis:Claim ; rdfs:label "Creditor Claim" .
owl:AllDisjointClasses [ owl:members ( fis:ResidualClaim fis:CreditorClaim ) ] .

fis:DebtSecurity a owl:Class ;
    rdfs:label "Debt Security" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Security
            [ a owl:Restriction ; owl:onProperty fis:hasClaim ; owl:someValuesFrom fis:CreditorClaim ]
        )
    ] ;
    rdfs:comment "Holder entitled to payment of principal and interest; the issuer is the debtor, the holder the creditor." .

fis:EquitySecurity a owl:Class ;
    rdfs:label "Equity Security" , "Stock" , "Share" , "Equity" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Security
            [ a owl:Restriction ; owl:onProperty fis:hasClaim ; owl:someValuesFrom fis:ResidualClaim ]
        )
    ] ;
    rdfs:comment "A share of equity/ownership interest in an entity; shares only in the residual value of the issuer after creditor claims are met." .

fis:HybridSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Hybrid Security" ;
    rdfs:comment "Combines some characteristics of both debt and equity securities (e.g. preferred stock, convertible bonds)." .

#################################################################
# ISSUER HIERARCHY
#################################################################

fis:Issuer a owl:Class ; rdfs:label "Issuer" ; rdfs:comment "The entity which is obligated on a security or financial instrument." .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "Sovereign Government" .
fis:LocalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "Local Government" , "Municipality" .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "Supranational Organization" .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "Corporation" .

owl:AllDisjointClasses [ owl:members (
    fis:SovereignGovernment fis:LocalGovernment fis:SupranationalOrganization fis:Corporation
) ] .

#################################################################
# CATEGORICAL FEATURE CLASSES
#################################################################

fis:OwnershipForm a owl:Class ; rdfs:label "Ownership Form" .
fis:BearerForm a owl:Class ; rdfs:subClassOf fis:OwnershipForm .
fis:RegisteredForm a owl:Class ; rdfs:subClassOf fis:OwnershipForm .
fis:BookEntryForm a owl:Class ; rdfs:subClassOf fis:OwnershipForm .
owl:AllDisjointClasses [ owl:members ( fis:BearerForm fis:RegisteredForm fis:BookEntryForm ) ] .

fis:CouponType a owl:Class ; rdfs:label "Coupon Type" .
fis:FixedCouponType a owl:Class ; rdfs:subClassOf fis:CouponType .
fis:FloatingCouponType a owl:Class ; rdfs:subClassOf fis:CouponType .
fis:ZeroCouponType a owl:Class ; rdfs:subClassOf fis:CouponType .
owl:AllDisjointClasses [ owl:members ( fis:FixedCouponType fis:FloatingCouponType fis:ZeroCouponType ) ] .

fis:DivisibilityForm a owl:Class ; rdfs:label "Divisibility Form" .
fis:DividedForm a owl:Class ; rdfs:subClassOf fis:DivisibilityForm .
fis:UndividedForm a owl:Class ; rdfs:subClassOf fis:DivisibilityForm .
owl:AllDisjointClasses [ owl:members ( fis:DividedForm fis:UndividedForm ) ] .

fis:RightType a owl:Class ; rdfs:label "Right Type" .
fis:BuyRight a owl:Class ; rdfs:subClassOf fis:RightType .
fis:SellRight a owl:Class ; rdfs:subClassOf fis:RightType .
owl:AllDisjointClasses [ owl:members ( fis:BuyRight fis:SellRight ) ] .

fis:ExerciseStyle a owl:Class ; rdfs:label "Exercise Style" .
fis:AmericanExerciseStyle a owl:Class ; rdfs:subClassOf fis:ExerciseStyle .
fis:EuropeanExerciseStyle a owl:Class ; rdfs:subClassOf fis:ExerciseStyle .
fis:BermudanExerciseStyle a owl:Class ; rdfs:subClassOf fis:ExerciseStyle .
owl:AllDisjointClasses [ owl:members ( fis:AmericanExerciseStyle fis:EuropeanExerciseStyle fis:BermudanExerciseStyle ) ] .

fis:Seniority a owl:Class ; rdfs:label "Seniority" .
fis:SeniorSeniority a owl:Class ; rdfs:subClassOf fis:Seniority .
fis:SubordinatedSeniority a owl:Class ; rdfs:subClassOf fis:Seniority .
owl:AllDisjointClasses [ owl:members ( fis:SeniorSeniority fis:SubordinatedSeniority ) ] .

fis:RepaymentSource a owl:Class ; rdfs:label "Repayment Source" .
fis:TaxingPower a owl:Class ; rdfs:subClassOf fis:RepaymentSource .
fis:RevenueStream a owl:Class ; rdfs:subClassOf fis:RepaymentSource .
fis:PropertyAssessment a owl:Class ; rdfs:subClassOf fis:RepaymentSource .
owl:AllDisjointClasses [ owl:members ( fis:TaxingPower fis:RevenueStream fis:PropertyAssessment ) ] .

fis:CollateralType a owl:Class ; rdfs:label "Collateral Type" .
fis:MortgageCollateral a owl:Class ; rdfs:subClassOf fis:CollateralType .
fis:DebtObligationCollateral a owl:Class ; rdfs:subClassOf fis:CollateralType .
fis:ConsumerLoanCollateral a owl:Class ; rdfs:subClassOf fis:CollateralType .
owl:AllDisjointClasses [ owl:members ( fis:MortgageCollateral fis:DebtObligationCollateral fis:ConsumerLoanCollateral ) ] .

fis:CreditRatingCategory a owl:Class ; rdfs:label "Credit Rating Category" .
fis:InvestmentGradeCategory a owl:Class ; rdfs:subClassOf fis:CreditRatingCategory .
fis:SpeculativeGradeCategory a owl:Class ; rdfs:subClassOf fis:CreditRatingCategory ; rdfs:label "Speculative Grade" , "High Yield" , "Junk" .
owl:AllDisjointClasses [ owl:members ( fis:InvestmentGradeCategory fis:SpeculativeGradeCategory ) ] .

fis:BondEmbeddedFeature a owl:Class ; rdfs:label "Bond Embedded Feature" .
fis:CallProvision a owl:Class ; rdfs:subClassOf fis:BondEmbeddedFeature .
fis:PutProvision a owl:Class ; rdfs:subClassOf fis:BondEmbeddedFeature .

fis:TriggerEvent a owl:Class ; rdfs:label "Trigger Event" ; rdfs:comment "Pre-specified event (e.g. capital ratio breach) that forces conversion of a contingent convertible." .

#################################################################
# BOND HIERARCHY
#################################################################

fis:Bond a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Bond" ;
    rdfs:comment "Issuer owes holder a debt and is obliged to repay principal at maturity plus interest (coupon). Classification dimensions (issuer, coupon type, ownership form, seniority, convertibility, embedded options) are not mutually exclusive." .

fis:GovernmentBond a owl:Class ;
    rdfs:label "Government Bond" , "Treasury Bond" , "Sovereign Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] .

fis:MunicipalBond a owl:Class ;
    rdfs:label "Municipal Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] .

fis:CorporateBond a owl:Class ;
    rdfs:label "Corporate Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

fis:SupranationalBond a owl:Class ;
    rdfs:label "Supranational Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .

fis:WarBond a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "War Bond" ;
    rdfs:comment "Issued by a government to fund military operations during wartime." .

fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "Climate Bond" , "Green Bond" .
fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "Social Impact Bond" .
fis:LotteryBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "Lottery Bond" .
fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "Serial Bond" ; rdfs:comment "Matures in installments over time." .

fis:GeneralObligationBond a owl:Class ;
    rdfs:subClassOf fis:MunicipalBond ;
    rdfs:label "General Obligation Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
        [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:TaxingPower ] ) ] .

fis:RevenueBond a owl:Class ;
    rdfs:subClassOf fis:MunicipalBond ;
    rdfs:label "Revenue Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
        [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:RevenueStream ] ) ] ;
    rdfs:comment "Typically non-recourse: repaid solely from revenues of a specified project." .

fis:AssessmentBond a owl:Class ;
    rdfs:subClassOf fis:GeneralObligationBond ;
    rdfs:label "Assessment Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
        [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:PropertyAssessment ] ) ] ;
    rdfs:comment "Considered a form of general obligation bond: government remains obligated to redeem in full even if assessments are insufficient." .

fis:CoveredBond a owl:Class ;
    rdfs:label "Covered Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasOnBalanceSheetCollateral ; owl:hasValue true ] ) ] ;
    rdfs:comment "Backed by cash flows from mortgages or public-sector assets that remain on the issuer's balance sheet." .

fis:AssetBackedSecurity a owl:Class ;
    rdfs:label "Asset-Backed Security" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasOnBalanceSheetCollateral ; owl:hasValue false ] ) ] ;
    rdfs:comment "Umbrella term for bonds backed by a pool of assets whose payments depend on underlying cash flows, unlike covered bonds, the assets are removed from the issuer's balance sheet (e.g. via a special purpose vehicle). Note: the corpus also uses 'ABS' narrowly to mean only consumer-loan-backed securities, distinct from MBS and CDO; both usages are recorded here." .

fis:MortgageBackedSecurity a owl:Class ;
    rdfs:label "Mortgage-Backed Security" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateralType ; owl:someValuesFrom fis:MortgageCollateral ] ) ] .

fis:CollateralizedDebtObligation a owl:Class ;
    rdfs:label "Collateralized Debt Obligation" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateralType ; owl:someValuesFrom fis:DebtObligationCollateral ] ) ] .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Residential Mortgage-Backed Security" ;
    rdfs:comment "Secured by single-family, one- to four-unit real estate." .

fis:CommercialMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Commercial Mortgage-Backed Security" ;
    rdfs:comment "Secured by commercial and multi-family properties." .

fis:CollateralizedMortgageObligation a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Collateralized Mortgage Obligation" , "Pay-Through Bond" .

fis:StrippedMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Stripped Mortgage-Backed Security" .

fis:InterestOnlyStrippedMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:StrippedMortgageBackedSecurity ; rdfs:label "Interest-Only Strip" .

fis:PrincipalOnlyStrippedMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:StrippedMortgageBackedSecurity ; rdfs:label "Principal-Only Strip" .

owl:AllDisjointClasses [ owl:members (
    fis:InterestOnlyStrippedMortgageBackedSecurity fis:PrincipalOnlyStrippedMortgageBackedSecurity
) ] .

fis:SeniorBond a owl:Class ;
    rdfs:label "Senior Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:someValuesFrom fis:SeniorSeniority ] ) ] .

fis:SubordinatedBond a owl:Class ;
    rdfs:label "Subordinated Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:someValuesFrom fis:SubordinatedSeniority ] ) ] .

fis:FixedRateBond a owl:Class ;
    rdfs:label "Fixed Rate Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:someValuesFrom fis:FixedCouponType ] ) ] .

fis:FloatingRateNote a owl:Class ;
    rdfs:label "Floating Rate Note" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:someValuesFrom fis:FloatingCouponType ] ) ] .

fis:ZeroCouponBond a owl:Class ;
    rdfs:label "Zero-Coupon Bond" , "Discount Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:someValuesFrom fis:ZeroCouponType ] ) ] ;
    rdfs:comment "Issued at a deep discount to par; sole return is the difference between purchase price and face value paid at maturity." .

fis:InflationIndexedBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Inflation-Indexed Bond" , "Linker" , "Index-Linked Bond" ;
    rdfs:comment "Principal and interest payments are indexed to a price index." .

fis:PerpetualBond a owl:Class ;
    rdfs:label "Perpetual Bond" , "Perpetuity" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:maxCardinality "0"^^xsd:nonNegativeInteger ] ) ] ;
    rdfs:comment "Has no maturity date; principal is repaid only at the discretion of the borrower, if ever." .

fis:BearerBond a owl:Class ;
    rdfs:label "Bearer Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasOwnershipForm ; owl:someValuesFrom fis:BearerForm ] ) ] .

fis:RegisteredBond a owl:Class ;
    rdfs:label "Registered Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasOwnershipForm ; owl:someValuesFrom fis:RegisteredForm ] ) ] .

fis:BookEntryBond a owl:Class ;
    rdfs:label "Book-Entry Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasOwnershipForm ; owl:someValuesFrom fis:BookEntryForm ] ) ] .

fis:CallableBond a owl:Class ;
    rdfs:label "Callable Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedFeature ; owl:someValuesFrom fis:CallProvision ] ) ] .

fis:PuttableBond a owl:Class ;
    rdfs:label "Puttable Bond" , "Retractable Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedFeature ; owl:someValuesFrom fis:PutProvision ] ) ] .

fis:BulletBond a owl:Class ;
    rdfs:label "Bullet Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedFeature ;
          owl:onClass fis:BondEmbeddedFeature ; owl:maxQualifiedCardinality "0"^^xsd:nonNegativeInteger ] ) ] ;
    rdfs:comment "A straight bond that is neither callable nor putable." .

fis:InvestmentGradeBond a owl:Class ;
    rdfs:label "Investment Grade Bond" , "High Grade Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingCategory ; owl:someValuesFrom fis:InvestmentGradeCategory ] ) ] .

fis:HighYieldBond a owl:Class ;
    rdfs:label "High-Yield Bond" , "Junk Bond" , "Non-Investment Grade Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingCategory ; owl:someValuesFrom fis:SpeculativeGradeCategory ] ) ] .

#################################################################
# CONVERTIBLE BONDS
#################################################################

fis:ConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity ;
    rdfs:label "Convertible Bond" , "Convertible Note" , "Convertible Debenture" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
    rdfs:comment "A bond that the holder can convert into a specified number of shares of common stock, or cash of equal value." .

fis:ExchangeableBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Exchangeable Bond" ;
    rdfs:comment "Allows exchange into shares of a corporation other than the issuer (differentiated from ConvertibleBond by the identity of the conversion-target issuer, not modelled structurally here)." .

fis:MandatoryConvertibleBond a owl:Class ;
    rdfs:label "Mandatory Convertible Bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:ConvertibleBond
        [ a owl:Restriction ; owl:onProperty fis:hasConversionObligation ; owl:hasValue true ] ) ] ;
    rdfs:comment "Forces the holder to convert into shares at maturity." .

fis:ContingentConvertibleBond a owl:Class ;
    rdfs:label "Contingent Convertible Bond" , "CoCo" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:ConvertibleBond
        [ a owl:Restriction ; owl:onProperty fis:hasConversionTrigger ; owl:someValuesFrom fis:TriggerEvent ] ) ] ;
    rdfs:comment "Automatically converted into equity if a pre-specified trigger event occurs." .

fis:PackagedConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:label "Packaged Convertible Bond" ;
    rdfs:comment "A straight bond and a call option/warrant wrapped together; legs may be traded separately." .

fis:SyntheticConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:label "Synthetic Convertible Bond" ;
    rdfs:comment "Issued by an investment bank to replicate a convertible payoff on a specific underlying equity, settled in cash." .

#################################################################
# MONEY MARKET INSTRUMENTS
#################################################################

fis:MoneyMarketInstrument a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Money Market Instrument" ;
    rdfs:comment "Short-term debt instrument, typically with an original maturity of one year or less." .

fis:CommercialPaper a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Commercial Paper" ;
    rdfs:comment "Unsecured promissory note with a fixed maturity usually of less than 270 days, issued by large corporations." .

fis:CertificateOfDeposit a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Certificate of Deposit" ;
    rdfs:comment "Time deposit sold by banks, thrifts, and credit unions with a specific, fixed term." .

fis:TreasuryBill a owl:Class ;
    rdfs:label "Treasury Bill" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
    rdfs:comment "Short-term debt obligation of a national government, maturing in three to twelve months (or one year or less), issued at a discount." .

fis:RepurchaseAgreement a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Repurchase Agreement" , "Repo" ;
    rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase them at a fixed price on a fixed date." .

fis:BankersAcceptance a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Banker's Acceptance" .

#################################################################
# EQUITY SECURITIES
#################################################################

fis:CommonStock a owl:Class ;
    rdfs:label "Common Stock" , "Ordinary Share" , "Voting Share" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:EquitySecurity
        [ a owl:Restriction ; owl:onProperty fis:hasVotingRights ; owl:hasValue true ] ) ] .

fis:PreferredStock a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity ;
    rdfs:label "Preferred Stock" , "Preference Share" , "Preferred Share" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:EquitySecurity
        [ a owl:Restriction ; owl:onProperty fis:hasDividendPriority ; owl:hasValue true ] ) ] ;
    rdfs:comment "Intermediate class between equity and debt: priority over common stock in dividends and liquidation, usually without voting rights." .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:CumulativePreferredStock a owl:Class ;
    rdfs:label "Cumulative Preferred Stock" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasDividendAccumulation ; owl:hasValue true ] ) ] .

fis:NonCumulativePreferredStock a owl:Class ;
    rdfs:label "Non-Cumulative Preferred Stock" , "Straight Preferred Stock" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasDividendAccumulation ; owl:hasValue false ] ) ] .

fis:ConvertiblePreferredStock a owl:Class ;
    rdfs:label "Convertible Preferred Stock" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] .

#################################################################
# DIVIDED / UNDIVIDED / FUNGIBLE SECURITIES
#################################################################

fis:DividedSecurity a owl:Class ;
    rdfs:label "Divided Security" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasDivisibility ; owl:someValuesFrom fis:DividedForm ] ) ] ;
    rdfs:comment "Each instrument constitutes a separate, legally distinct asset/debt." .

fis:UndividedSecurity a owl:Class ;
    rdfs:label "Undivided Security" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasDivisibility ; owl:someValuesFrom fis:UndividedForm ] ) ] ;
    rdfs:comment "The entire issue is one single asset; each security is a fractional part of the undivided whole." .

fis:FungibleSecurity a owl:Class ;
    rdfs:label "Fungible Security" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:isFungible ; owl:hasValue true ] ) ] ;
    rdfs:comment "All holdings of the security are treated identically and are interchangeable." .

fis:BearerSecurity a owl:Class ;
    rdfs:label "Bearer Security" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasOwnershipForm ; owl:someValuesFrom fis:BearerForm ] ) ] .

fis:RegisteredSecurity a owl:Class ;
    rdfs:label "Registered Security" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasOwnershipForm ; owl:someValuesFrom fis:RegisteredForm ] ) ] .

#################################################################
# DEPOSITARY RECEIPTS
#################################################################

fis:DepositaryReceipt a owl:Class ;
    rdfs:label "Depositary Receipt" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
    rdfs:comment "Negotiable instrument issued by a bank representing a foreign company's publicly traded securities, trading on a local exchange." .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "American Depositary Receipt" .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "European Depositary Receipt" .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "Global Depositary Receipt" .

#################################################################
# FUNDS
#################################################################

fis:Fund a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Fund" , "Investment Fund" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasPortfolioHolding ; owl:someValuesFrom fis:FinancialInstrument ] ) ] ;
    rdfs:comment "Pools money from many investors to purchase a portfolio of securities." .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:Fund ; rdfs:label "Mutual Fund" .
fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:Fund ; rdfs:label "Exchange-Traded Fund" , "ETF" .
fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:Fund ; rdfs:label "Hedge Fund" .

owl:AllDisjointClasses [ owl:members ( fis:MutualFund fis:ExchangeTradedFund fis:HedgeFund ) ] .

fis:MoneyMarketFund a owl:Class ;
    rdfs:label "Money Market Fund" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Fund
        [ a owl:Restriction ; owl:onProperty fis:hasPortfolioHolding ; owl:someValuesFrom fis:MoneyMarketInstrument ] ) ] .

fis:BondFund a owl:Class ;
    rdfs:label "Bond Fund" , "Income Fund" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Fund
        [ a owl:Restriction ; owl:onProperty fis:hasPortfolioHolding ; owl:someValuesFrom fis:Bond ] ) ] .

fis:EquityFund a owl:Class ;
    rdfs:label "Equity Fund" , "Stock Fund" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Fund
        [ a owl:Restriction ; owl:onProperty fis:hasPortfolioHolding ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:IndexFund a owl:Class ;
    rdfs:label "Index Fund" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Fund
        [ a owl:Restriction ; owl:onProperty fis:hasTrackedIndex ; owl:someValuesFrom fis:MarketIndex ] ) ] ;
    rdfs:comment "Passively managed fund that tracks the performance of a market or bond index." .

fis:ActivelyManagedFund a owl:Class ;
    rdfs:subClassOf fis:Fund ;
    rdfs:label "Actively Managed Fund" ;
    rdfs:comment "Seeks to outperform an index through active security selection." .

owl:AllDisjointClasses [ owl:members ( fis:IndexFund fis:ActivelyManagedFund ) ] .

fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:Fund ; rdfs:label "Open-End Fund" .
fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:Fund ; rdfs:label "Closed-End Fund" .
fis:UnitInvestmentTrust a owl:Class ; rdfs:subClassOf fis:Fund ; rdfs:label "Unit Investment Trust" .

owl:AllDisjointClasses [ owl:members ( fis:OpenEndFund fis:ClosedEndFund fis:UnitInvestmentTrust ) ] .

#################################################################
# DIVIDEND
#################################################################

fis:Dividend a owl:Class ; rdfs:label "Dividend" ; rdfs:comment "A discretionary portion of a company's profit paid to shareholders; not a contractual obligation, unlike a bond coupon." .
fis:CashDividend a owl:Class ; rdfs:subClassOf fis:Dividend ; rdfs:label "Cash Dividend" .
fis:StockDividend a owl:Class ; rdfs:subClassOf fis:Dividend ; rdfs:label "Stock Dividend" .
owl:AllDisjointClasses [ owl:members ( fis:CashDividend fis:StockDividend ) ] .

#################################################################
# HOLDERS
#################################################################

fis:Holder a owl:Class ; rdfs:label "Holder" .
fis:Shareholder a owl:Class ; rdfs:subClassOf fis:Holder ; rdfs:label "Shareholder" , "Stockholder" .
fis:Bondholder a owl:Class ; rdfs:subClassOf fis:Holder ; rdfs:label "Bondholder" .

#################################################################
# DERIVATIVES: OPTION
#################################################################

fis:Option a owl:Class ;
    rdfs:subClassOf fis:DerivativeInstrument ;
    rdfs:label "Option" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:DerivativeInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Asset ]
            [ a owl:Restriction ; owl:onProperty fis:hasStrikePrice ; owl:someValuesFrom xsd:decimal ]
            [ a owl:Restriction ; owl:onProperty fis:hasExpirationDate ; owl:someValuesFrom xsd:date ]
        )
    ] ;
    rdfs:comment "Contract giving the holder the right, but not the obligation, to buy or sell the underlying at the strike price on or before the expiration date." .

fis:CallOption a owl:Class ;
    rdfs:label "Call Option" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasRightType ; owl:someValuesFrom fis:BuyRight ] ) ] .

fis:PutOption a owl:Class ;
    rdfs:label "Put Option" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasRightType ; owl:someValuesFrom fis:SellRight ] ) ] .

fis:AmericanOption a owl:Class ;
    rdfs:label "American Option" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:someValuesFrom fis:AmericanExerciseStyle ] ) ] .

fis:EuropeanOption a owl:Class ;
    rdfs:label "European Option" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:someValuesFrom fis:EuropeanExerciseStyle ] ) ] .

fis:BermudanOption a owl:Class ;
    rdfs:label "Bermudan Option" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:someValuesFrom fis:BermudanExerciseStyle ] ) ] .

fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ; rdfs:label "Asian Option" ; rdfs:comment "Payoff determined by the average underlying price over a preset period." .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ; rdfs:label "Barrier Option" .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ; rdfs:label "Binary Option" ; rdfs:comment "All-or-nothing payoff." .
fis:ExoticOption a owl:Class ; rdfs:subClassOf fis:Option ; rdfs:label "Exotic Option" .

fis:Warrant a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Warrant" ;
    rdfs:comment "A long-dated option, generally traded over the counter. The corpus elsewhere groups equity warrants under 'hybrid securities' (a Security classification); to avoid conflict with the CashInstrument/DerivativeInstrument disjointness, this ontology classifies Warrant as a DerivativeInstrument (Option), consistent with the derivatives-taxonomy passages." .

fis:EquityWarrant a owl:Class ;
    rdfs:label "Equity Warrant" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Warrant
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
    rdfs:comment "Allows the holder to purchase a specific number of shares at a specified price within a specified time." .

owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

#################################################################
# DERIVATIVES: FORWARD / FUTURE
#################################################################

fis:Future a owl:Class ;
    rdfs:label "Future" , "Futures Contract" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:DerivativeInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Asset ]
            [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue true ]
        )
    ] ;
    rdfs:comment "A standardized contract written by a clearing house that operates an exchange, obligating both parties to transact at a future date." .

fis:Forward a owl:Class ;
    rdfs:label "Forward" , "Forward Contract" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:DerivativeInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Asset ]
            [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue false ]
        )
    ] ;
    rdfs:comment "A non-standardized, over-the-counter contract between two parties." .

#################################################################
# DERIVATIVES: SWAP
#################################################################

fis:Swap a owl:Class ;
    rdfs:subClassOf fis:DerivativeInstrument ;
    rdfs:label "Swap" ;
    rdfs:comment "Two counterparties exchange streams of cash flows ('legs') of one party's financial instrument for those of the other's." .

fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap ; rdfs:label "Interest Rate Swap" .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap ; rdfs:label "Currency Swap" , "Cross-Currency Swap" .

fis:CreditDefaultSwap a owl:Class ;
    rdfs:label "Credit Default Swap" , "CDS" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
        [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:Issuer ] ) ] ;
    rdfs:comment "Seller compensates the buyer in the event of a loan default or other credit event on the reference entity." .

owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap ) ] .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Issuer ;
    rdfs:label "has issuer" .

fis:isIssuerOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasIssuer ;
    rdfs:domain fis:Issuer ;
    rdfs:range fis:Security ;
    rdfs:label "is issuer of" .

fis:hasUnderlying a owl:ObjectProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:Asset ;
    rdfs:label "has underlying" .

fis:isUnderlyingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasUnderlying ;
    rdfs:domain fis:Asset ;
    rdfs:range fis:FinancialInstrument ;
    rdfs:label "is underlying of" .

fis:hasClaim a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Claim ;
    rdfs:label "has claim" .

fis:hasOwnershipForm a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:OwnershipForm ;
    rdfs:label "has ownership form" .

fis:hasCouponType a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range fis:CouponType ;
    rdfs:label "has coupon type" .

fis:hasDivisibility a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:DivisibilityForm ;
    rdfs:label "has divisibility" .

fis:hasRightType a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range fis:RightType ;
    rdfs:label "has right type" .

fis:hasExerciseStyle a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range fis:ExerciseStyle ;
    rdfs:label "has exercise style" .

fis:hasSeniority a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range fis:Seniority ;
    rdfs:label "has seniority" .

fis:hasRepaymentSource a owl:ObjectProperty ;
    rdfs:domain fis:MunicipalBond ;
    rdfs:range fis:RepaymentSource ;
    rdfs:label "has repayment source" .

fis:hasCollateralType a owl:ObjectProperty ;
    rdfs:domain fis:AssetBackedSecurity ;
    rdfs:range fis:CollateralType ;
    rdfs:label "has collateral type" .

fis:hasCreditRatingCategory a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range fis:CreditRatingCategory ;
    rdfs:label "has credit rating category" .

fis:hasConversionTarget a owl:ObjectProperty ;
    rdfs:domain fis:HybridSecurity ;
    rdfs:range fis:EquitySecurity ;
    rdfs:label "has conversion target" .

fis:hasConversionTrigger a owl:ObjectProperty ;
    rdfs:domain fis:ConvertibleBond ;
    rdfs:range fis:TriggerEvent ;
    rdfs:label "has conversion trigger" .

fis:hasEmbeddedFeature a owl:ObjectProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range fis:BondEmbeddedFeature ;
    rdfs:label "has embedded feature" .

fis:hasReferenceEntity a owl:ObjectProperty ;
    rdfs:domain fis:CreditDefaultSwap ;
    rdfs:range fis:Issuer ;
    rdfs:label "has reference entity" .

fis:hasPortfolioHolding a owl:ObjectProperty ;
    rdfs:domain fis:Fund ;
    rdfs:range fis:FinancialInstrument ;
    rdfs:label "has portfolio holding" .

fis:hasTrackedIndex a owl:ObjectProperty ;
    rdfs:domain fis:Fund ;
    rdfs:range fis:MarketIndex ;
    rdfs:label "has tracked index" .

fis:hasDividend a owl:ObjectProperty ;
    rdfs:domain fis:EquitySecurity ;
    rdfs:range fis:Dividend ;
    rdfs:label "has dividend" .

fis:hasHolder a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Holder ;
    rdfs:label "has holder" .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:isTradable a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range xsd:boolean ;
    rdfs:label "is tradable" .

fis:isFungible a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:boolean ;
    rdfs:label "is fungible" .

fis:isStandardized a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DerivativeInstrument ;
    rdfs:range xsd:boolean ;
    rdfs:label "is standardized" .

fis:isExchangeTraded a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range xsd:boolean ;
    rdfs:label "is exchange traded" .

fis:hasOnBalanceSheetCollateral a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:boolean ;
    rdfs:label "has on-balance-sheet collateral" .

fis:hasVotingRights a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:EquitySecurity ;
    rdfs:range xsd:boolean ;
    rdfs:label "has voting rights" .

fis:hasDividendPriority a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:EquitySecurity ;
    rdfs:range xsd:boolean ;
    rdfs:label "has dividend priority" .

fis:hasDividendAccumulation a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:PreferredStock ;
    rdfs:range xsd:boolean ;
    rdfs:label "has dividend accumulation" .

fis:hasConversionObligation a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:ConvertibleBond ;
    rdfs:range xsd:boolean ;
    rdfs:label "has conversion obligation" .

fis:hasFaceValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:decimal ;
    rdfs:label "has face value" , "has par value" , "has principal amount" .

fis:hasCouponRate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal ;
    rdfs:label "has coupon rate" .

fis:hasMaturityDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
