```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology" ;
    rdfs:comment "An OWL ontology modelling securities, bonds, equities, hybrid securities, derivatives, investment funds and related accounting classifications, derived from a corpus on financial securities." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

fis:Asset a owl:Class ;
    rdfs:label "asset" .

fis:FinancialInstrument a owl:Class ;
    rdfs:subClassOf fis:Asset ;
    rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled (IAS 32: any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another)." .

fis:CashInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:comment "An instrument whose value is determined directly by the markets, e.g. securities, loans and deposits." .

fis:Derivative a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:comment "A contract whose value is derived from the value and characteristics of one or more underlying entities such as an asset, index, rate or event. NOTE: One US-focused passage classifies derivatives as a category of security alongside debt and equity, while other passages treat securities (cash instruments) and derivatives as mutually exclusive categories of financial instrument. This ontology follows the majority/more detailed treatment and models Derivative as disjoint from CashInstrument." .

owl:AllDisjointClasses [ owl:members ( fis:CashInstrument fis:Derivative ) ] .

fis:Security a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "security" , "financial instrument (narrow sense)" ;
    rdfs:comment "A tradable financial asset; a financial contract which entitles the holder to investment returns and which can be enforced by law." .

fis:Loan a owl:Class ;
    rdfs:subClassOf fis:CashInstrument .

fis:Deposit a owl:Class ;
    rdfs:subClassOf fis:CashInstrument .

#################################################################
# SUPPORTING CLASSES: ISSUERS, HOLDERS, RIGHTS, STYLES, COLLATERAL
#################################################################

fis:Issuer a owl:Class ;
    rdfs:comment "The entity which is obligated on a security or other financial instrument." .

fis:SovereignGovernment rdfs:subClassOf fis:Issuer .
fis:LocalGovernment rdfs:subClassOf fis:Issuer ;
    rdfs:comment "A state, provincial, territorial, municipal or other sub-sovereign governmental unit." .
fis:SupranationalOrganization rdfs:subClassOf fis:Issuer .
fis:Corporation rdfs:subClassOf fis:Issuer .

owl:AllDisjointClasses [ owl:members ( fis:SovereignGovernment fis:LocalGovernment fis:SupranationalOrganization fis:Corporation ) ] .

fis:Holder a owl:Class ;
    rdfs:comment "An entity that holds rights under a security." .

fis:Shareholder a owl:Class ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf ( fis:Holder
            [ a owl:Restriction ; owl:onProperty fis:isHolderOf ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
    rdfs:comment "An individual or company that legally owns one or more shares of stock in a company." .

fis:Bondholder a owl:Class ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf ( fis:Holder
            [ a owl:Restriction ; owl:onProperty fis:isHolderOf ; owl:someValuesFrom fis:Bond ] ) ] .

fis:Right a owl:Class .
fis:RightToBuy rdfs:subClassOf fis:Right .
fis:RightToSell rdfs:subClassOf fis:Right .
owl:AllDisjointClasses [ owl:members ( fis:RightToBuy fis:RightToSell ) ] .

fis:ExerciseStyle a owl:Class .
fis:AmericanExerciseStyle rdfs:subClassOf fis:ExerciseStyle ;
    rdfs:comment "May be exercised on any trading day on or before expiration." .
fis:EuropeanExerciseStyle rdfs:subClassOf fis:ExerciseStyle ;
    rdfs:comment "May only be exercised on the expiry date." .
fis:BermudanExerciseStyle rdfs:subClassOf fis:ExerciseStyle ;
    rdfs:comment "May be exercised only on specified dates on or before expiration." .
owl:AllDisjointClasses [ owl:members ( fis:AmericanExerciseStyle fis:EuropeanExerciseStyle fis:BermudanExerciseStyle ) ] .

fis:Mortgage rdfs:subClassOf fis:Asset .
fis:ResidentialMortgage rdfs:subClassOf fis:Mortgage .
fis:CommercialMortgage rdfs:subClassOf fis:Mortgage .
owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgage fis:CommercialMortgage ) ] .

fis:MarketIndex rdfs:subClassOf fis:Asset .

fis:Investor a owl:Class .
fis:RetailInvestor rdfs:subClassOf fis:Investor ;
    rdfs:comment "Members of the public investing personally, other than by way of business." .
fis:WholesaleInvestor rdfs:subClassOf fis:Investor ;
    rdfs:comment "A financial institution acting on its own account or on behalf of clients, e.g. investment banks, insurance companies, pension funds." .
owl:AllDisjointClasses [ owl:members ( fis:RetailInvestor fis:WholesaleInvestor ) ] .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Issuer .

fis:isIssuerOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasIssuer ;
    rdfs:domain fis:Issuer ;
    rdfs:range fis:Security .

fis:hasHolder a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Holder .

fis:isHolderOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasHolder ;
    rdfs:domain fis:Holder ;
    rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain [ a owl:Class ; owl:unionOf ( fis:Derivative fis:DepositaryReceipt ) ] ;
    rdfs:range fis:Asset ;
    rdfs:comment "The item (the underlier) that can or must be bought or sold, or on which a depositary receipt is based." .

fis:isUnderlyingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasUnderlying ;
    rdfs:domain fis:Asset ;
    rdfs:range [ a owl:Class ; owl:unionOf ( fis:Derivative fis:DepositaryReceipt ) ] .

fis:hasCollateral a owl:ObjectProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range fis:Asset .

fis:isCollateralOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasCollateral ;
    rdfs:domain fis:Asset ;
    rdfs:range fis:DebtSecurity .

fis:hasConversionTarget a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:HybridSecurity ;
    rdfs:range fis:EquitySecurity ;
    rdfs:comment "The class of shares into which a hybrid security (e.g. convertible bond, convertible preferred stock) may be converted." .

fis:hasReferenceEntity a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:CreditDefaultSwap ;
    rdfs:range fis:DebtSecurity ;
    rdfs:comment "The debt obligation whose credit risk a credit default swap references." .

fis:hasTrackedIndex a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:InvestmentFund ;
    rdfs:range fis:MarketIndex .

fis:hasRight a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range fis:Right .

fis:hasExerciseStyle a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range fis:ExerciseStyle .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ;
    rdfs:comment "Nominal, principal, par or face amount on which the issuer pays interest and which is repaid at maturity." .

fis:hasCouponRate a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:decimal .

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:date .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ; rdfs:range xsd:date .

fis:hasCreditRating a owl:DatatypeProperty ;
    rdfs:domain fis:DebtSecurity ; rdfs:range xsd:string .

fis:hasYieldToMaturity a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:decimal .

fis:hasConversionRatio a owl:DatatypeProperty ;
    rdfs:domain fis:HybridSecurity ; rdfs:range xsd:decimal .

fis:hasCallProvision a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:boolean .

fis:hasPutProvision a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:boolean .

fis:hasParValue a owl:DatatypeProperty ;
    rdfs:domain fis:EquitySecurity ; rdfs:range xsd:decimal .

fis:hasDividendRate a owl:DatatypeProperty ;
    rdfs:domain fis:PreferredStock ; rdfs:range xsd:decimal .

fis:hasVotingRights a owl:DatatypeProperty ;
    rdfs:domain fis:EquitySecurity ; rdfs:range xsd:boolean .

fis:hasPhysicalCertificate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ; rdfs:range xsd:boolean .

fis:hasBearerForm a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ; rdfs:range xsd:boolean .

fis:hasUndividedForm a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ; rdfs:range xsd:boolean .

fis:hasFungibility a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ; rdfs:range xsd:boolean .

fis:hasPublicOffering a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ; rdfs:range xsd:boolean .

fis:hasOriginalMaturityInDays a owl:DatatypeProperty ;
    rdfs:domain fis:MoneyMarketInstrument ; rdfs:range xsd:integer .

fis:hasFullFaithAndCreditBacking a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:MunicipalBond ; rdfs:range xsd:boolean .

fis:hasFundingPurpose a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:string .

#################################################################
# SECURITY: TOP-LEVEL CLASSIFICATION
#################################################################

fis:DebtSecurity rdfs:subClassOf fis:Security ;
    rdfs:comment "Issuer owes the holder a debt and is obliged to repay principal plus interest (coupon)." .

fis:EquitySecurity rdfs:subClassOf fis:Security ;
    rdfs:comment "A share of equity interest in an entity; a residual claim on the assets of the entity after all creditor claims have been met." .

fis:HybridSecurity rdfs:subClassOf fis:Security ;
    rdfs:comment "Combines characteristics of both debt and equity securities. NOTE: preferred stock is classified both as EquitySecurity (a form of capital stock) and as HybridSecurity by the corpus; this ontology therefore does not assert HybridSecurity disjoint from DebtSecurity/EquitySecurity." .

owl:AllDisjointClasses [ owl:members ( fis:DebtSecurity fis:EquitySecurity ) ] .

fis:InvestmentFund rdfs:subClassOf fis:Security ;
    rdfs:comment "An investment fund that pools money from many investors to purchase securities." .

fis:DepositaryReceipt rdfs:subClassOf fis:Security ;
    rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities." .

#################################################################
# SECURITY FORM / CLASSIFICATION DIMENSIONS
#################################################################

fis:CertificatedSecurity owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasPhysicalCertificate ; owl:hasValue "true"^^xsd:boolean ] ) ] .
fis:NonCertificatedSecurity owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasPhysicalCertificate ; owl:hasValue "false"^^xsd:boolean ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:CertificatedSecurity fis:NonCertificatedSecurity ) ] .

fis:BearerSecurity owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasBearerForm ; owl:hasValue "true"^^xsd:boolean ] ) ] ;
    rdfs:comment "Entitles the holder to rights merely by holding the certificate." .
fis:RegisteredSecurity owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasBearerForm ; owl:hasValue "false"^^xsd:boolean ] ) ] ;
    rdfs:comment "Entitles the holder to rights only if recorded on a security register." .
owl:AllDisjointClasses [ owl:members ( fis:BearerSecurity fis:RegisteredSecurity ) ] .

fis:DividedSecurity owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasUndividedForm ; owl:hasValue "false"^^xsd:boolean ] ) ] ;
    rdfs:comment "Each instrument constitutes a separate asset/debt, legally distinct from each other instrument in the issue." .
fis:UndividedSecurity owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasUndividedForm ; owl:hasValue "true"^^xsd:boolean ] ) ] ;
    rdfs:comment "The entire issue makes up one asset, with each security a fractional part of the undivided whole." .
owl:AllDisjointClasses [ owl:members ( fis:DividedSecurity fis:UndividedSecurity ) ] .

fis:FungibleSecurity owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasFungibility ; owl:hasValue "true"^^xsd:boolean ] ) ] .
fis:NonFungibleSecurity owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasFungibility ; owl:hasValue "false"^^xsd:boolean ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:FungibleSecurity fis:NonFungibleSecurity ) ] .

fis:PubliclyOfferedSecurity owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasPublicOffering ; owl:hasValue "true"^^xsd:boolean ] ) ] .
fis:PrivatelyPlacedSecurity owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasPublicOffering ; owl:hasValue "false"^^xsd:boolean ] ) ] ;
    rdfs:comment "Offered privately to a limited number of qualified persons; not publicly tradable." .
owl:AllDisjointClasses [ owl:members ( fis:PubliclyOfferedSecurity fis:PrivatelyPlacedSecurity ) ] .

#################################################################
# BOND AND SUBCLASSES
#################################################################

fis:Bond rdfs:subClassOf fis:DebtSecurity ;
    rdfs:comment "A security under which the issuer owes the holder a debt and is obliged to pay principal at maturity and, usually, periodic coupon interest." .

fis:MoneyMarketInstrument rdfs:subClassOf fis:DebtSecurity ;
    rdfs:comment "Short-term debt instrument with original maturity of one year or less." .

owl:AllDisjointClasses [ owl:members ( fis:Bond fis:MoneyMarketInstrument ) ] .

fis:Debenture rdfs:subClassOf fis:Bond ;
    rdfs:label "unsecured bond" ;
    rdfs:comment "An unsecured debt security having only a general claim on the issuer's assets and cash flows." .

fis:SecuredBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:SecuredBond fis:Debenture ) ] .

fis:MortgageBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:SecuredBond
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] ;
    rdfs:comment "A bond secured by the pledge of specific mortgage assets." .

fis:CollateralTrustBond rdfs:subClassOf fis:SecuredBond .
fis:EquipmentTrustCertificate rdfs:subClassOf fis:SecuredBond .
fis:GuaranteedBond rdfs:subClassOf fis:Bond .

fis:GovernmentBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
    rdfs:label "sovereign bond" , "treasury bond (generic)" .

fis:CorporateBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

fis:MunicipalBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] ;
    rdfs:label "muni" .

fis:SupranationalBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] ;
    rdfs:label "supra" .

owl:AllDisjointClasses [ owl:members ( fis:GovernmentBond fis:CorporateBond fis:MunicipalBond fis:SupranationalBond ) ] ;
    rdfs:comment "Modelled as mutually exclusive by issuer type, although the corpus notes the term 'corporate bond' sometimes also encompasses supranational issuance." .

fis:EuroBond rdfs:subClassOf fis:Bond ;
    rdfs:comment "Issued internationally outside the domestic market in a currency different from the issuer's domicile; characteristically unsecured, underwritten, interest paid gross." .
fis:EuroNote rdfs:subClassOf fis:MoneyMarketInstrument .

fis:USTreasurySecurity rdfs:subClassOf fis:GovernmentBond ;
    rdfs:comment "A United States Treasury security, issued by the US Department of the Treasury." .

fis:TreasuryBill rdfs:subClassOf fis:USTreasurySecurity, fis:MoneyMarketInstrument .
fis:TreasuryNote rdfs:subClassOf fis:USTreasurySecurity .
fis:TreasuryBond rdfs:subClassOf fis:USTreasurySecurity .
fis:TreasuryInflationProtectedSecurity rdfs:subClassOf fis:USTreasurySecurity .

owl:AllDisjointClasses [ owl:members ( fis:TreasuryBill fis:TreasuryNote fis:TreasuryBond fis:TreasuryInflationProtectedSecurity ) ] .

fis:GeneralObligationBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
        [ a owl:Restriction ; owl:onProperty fis:hasFullFaithAndCreditBacking ; owl:hasValue "true"^^xsd:boolean ] ) ] .

fis:RevenueBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:MunicipalBond
        [ a owl:Restriction ; owl:onProperty fis:hasFullFaithAndCreditBacking ; owl:hasValue "false"^^xsd:boolean ] ) ] ;
    rdfs:comment "Repaid solely from revenues generated by a specified revenue-generating entity; typically non-recourse." .

owl:AllDisjointClasses [ owl:members ( fis:GeneralObligationBond fis:RevenueBond ) ] .

fis:AssessmentBond rdfs:subClassOf fis:GeneralObligationBond ;
    rdfs:comment "Repayment is promised from property-tax assessments; generally treated as a form of general obligation bond." .

fis:WarBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasFundingPurpose ; owl:hasValue "militaryOperations" ] ) ] .
fis:ClimateBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasFundingPurpose ; owl:hasValue "climateChangeMitigationOrAdaptation" ] ) ] .
fis:SocialImpactBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasFundingPurpose ; owl:hasValue "socialOutcome" ] ) ] .

fis:ConvertibleBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] ;
    rdfs:comment "A bond or preferred stock that the holder may convert into the ordinary shares of the issuing company." .
fis:ConvertibleBond rdfs:subClassOf fis:HybridSecurity .

fis:ZeroCouponBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] ;
    rdfs:comment "Pays no regular interest; issued at a substantial discount to par value, redeemed at full principal at maturity." .

fis:FixedRateBond rdfs:subClassOf fis:Bond ;
    rdfs:comment "Coupon rate remains constant throughout the life of the bond." .
fis:FloatingRateNote rdfs:subClassOf fis:Bond ;
    rdfs:label "floater" ;
    rdfs:comment "Coupon varies throughout the life of the bond, linked to a reference rate such as LIBOR/SOFR/Euribor." .

owl:AllDisjointClasses [ owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) ] .

fis:PerpetualBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:cardinality "0"^^xsd:nonNegativeInteger ] ) ] ;
    rdfs:label "perpetuity" , "perp" ;
    rdfs:comment "A bond with no maturity date; principal is repaid only at the discretion of the issuer, if at all." .

fis:CallableBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCallProvision ; owl:hasValue "true"^^xsd:boolean ] ) ] ;
    rdfs:comment "Gives the issuer the right to repay the bond before the maturity date." .
fis:PutableBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasPutProvision ; owl:hasValue "true"^^xsd:boolean ] ) ] ;
    rdfs:label "retractable bond" ;
    rdfs:comment "Gives the holder the right to force the issuer to repay the bond before the maturity date." .

fis:SeniorBond rdfs:subClassOf fis:Bond ;
    rdfs:comment "Contractually prioritised over other unsecured debt in a bankruptcy of the issuer." .
fis:SubordinatedBond rdfs:subClassOf fis:Bond ;
    rdfs:comment "Has lower priority than senior bonds of the issuer in liquidation." .
owl:AllDisjointClasses [ owl:members ( fis:SeniorBond fis:SubordinatedBond ) ] .

fis:InvestmentGradeBond rdfs:subClassOf fis:CorporateBond ;
    rdfs:label "high grade bond" .
fis:HighYieldBond rdfs:subClassOf fis:CorporateBond ;
    rdfs:label "junk bond" , "non-investment grade bond" ;
    rdfs:comment "Rated below investment grade; investors expect a higher yield to compensate for higher default risk." .
owl:AllDisjointClasses [ owl:members ( fis:InvestmentGradeBond fis:HighYieldBond ) ] .

fis:BearerBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] ;
    rdfs:comment "An official certificate issued without a named holder; claimable by whoever possesses it." .
fis:RegisteredBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] ;
    rdfs:comment "Ownership is recorded by the issuer or a transfer agent; the opposite of a bearer bond." .
fis:BookEntryBond owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:NonCertificatedSecurity ) ] ;
    rdfs:comment "A bond that does not have a paper certificate." .

#################################################################
# ASSET-BACKED SECURITIES
#################################################################

fis:AssetBackedSecurity rdfs:subClassOf fis:Bond ;
    rdfs:label "ABS" ;
    rdfs:comment "A structured bond backed by a pool of assets whose cash flows service interest and principal payments." .

fis:CoveredBond rdfs:subClassOf fis:SecuredBond ;
    rdfs:comment "Backed by cash flows from mortgages or public-sector assets; unlike asset-backed securities, the assets remain on the issuer's balance sheet." .
owl:AllDisjointClasses [ owl:members ( fis:CoveredBond fis:AssetBackedSecurity ) ] .

fis:MortgageBackedSecurity owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] ;
    rdfs:label "MBS" .

fis:ResidentialMortgageBackedSecurity owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] ;
    rdfs:label "RMBS" .

fis:CommercialMortgageBackedSecurity owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CommercialMortgage ] ) ] ;
    rdfs:label "CMBS" .

owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) ] .

fis:CollateralizedMortgageObligation rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "CMO" , "pay-through bond" .

fis:CollateralizedDebtObligation owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtSecurity ] ) ] ;
    rdfs:label "CDO" .

owl:AllDisjointClasses [ owl:members ( fis:MortgageBackedSecurity fis:CollateralizedDebtObligation ) ] .

#################################################################
# MONEY MARKET INSTRUMENTS
#################################################################

fis:CommercialPaper rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:comment "An unsecured promissory note with a fixed maturity usually of less than 270 days." .
fis:CertificateOfDeposit rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "CD" ;
    rdfs:comment "A time deposit sold by banks, thrift institutions and credit unions with a specific, fixed term." .
fis:BankersAcceptance rdfs:subClassOf fis:MoneyMarketInstrument .
fis:RepurchaseAgreement rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "repo" ;
    rdfs:comment "A short-term loan arranged by selling securities with an agreement to repurchase them at a fixed price on a fixed date." .

owl:AllDisjointClasses [ owl:members ( fis:CommercialPaper fis:CertificateOfDeposit fis:BankersAcceptance fis:RepurchaseAgreement fis:TreasuryBill ) ] .

#################################################################
# EQUITY SECURITIES
#################################################################

fis:CommonStock rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "ordinary share" , "voting share" ;
    rdfs:comment "Typically carries voting rights and a residual claim on profits and liquidation proceeds, subordinate to preferred stock and all creditors." .

fis:PreferredStock rdfs:subClassOf fis:EquitySecurity, fis:HybridSecurity ;
    rdfs:label "preference share" , "preferred share" ;
    rdfs:comment "Senior to common stock but subordinate to bonds; has priority over common stock in dividends and liquidation; usually lacks voting rights. Classified by the corpus as both a form of capital stock (equity) and a hybrid instrument." .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:ConvertiblePreferredStock owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] ;
    rdfs:comment "Preferred stock that includes the ability of the holder to convert into a fixed number of common shares." .

#################################################################
# DEPOSITARY RECEIPTS
#################################################################

fis:AmericanDepositaryReceipt rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "ADR" ;
    rdfs:comment "A depositary receipt listed and traded in the United States." .
fis:EuropeanDepositaryReceipt rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "EDR" ;
    rdfs:comment "Issued by European banks." .
fis:GlobalDepositaryReceipt rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "GDR" .

owl:AllDisjointClasses [ owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) ] .

#################################################################
# INVESTMENT FUNDS
#################################################################

fis:MutualFund rdfs:subClassOf fis:InvestmentFund ;
    rdfs:comment "An SEC-registered open-end investment company that pools money from many investors; shares transact at next-calculated net asset value." .
fis:ExchangeTradedFund rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "ETF" ;
    rdfs:comment "Shares trade continuously on national securities exchanges at market prices that may differ from net asset value." .
fis:HedgeFund rdfs:subClassOf fis:InvestmentFund ;
    rdfs:comment "Pools money from investors with fewer regulatory protections and more flexible, risk-tolerant strategies than mutual funds." .
fis:MoneyMarketFund rdfs:subClassOf fis:InvestmentFund ;
    rdfs:comment "Invests primarily in money market instruments and other liquid, low-risk short-term debt." .
fis:BondFund rdfs:subClassOf fis:InvestmentFund .
fis:EquityFund rdfs:subClassOf fis:InvestmentFund .

owl:AllDisjointClasses [ owl:members ( fis:MutualFund fis:ExchangeTradedFund fis:HedgeFund ) ] .

fis:IndexFund owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:hasTrackedIndex ; owl:someValuesFrom fis:MarketIndex ] ) ] ;
    rdfs:comment "A passively managed fund designed to achieve approximately the same return as a particular market index." .

#################################################################
# DERIVATIVES
#################################################################

fis:LockProduct rdfs:subClassOf fis:Derivative ;
    rdfs:comment "Obligates the contractual parties to the terms over the life of the contract (e.g. swaps, futures, forwards)." .
fis:OptionProduct rdfs:subClassOf fis:Derivative ;
    rdfs:comment "Provides the buyer the right, but not the obligation, to enter the contract under the terms specified." .
owl:AllDisjointClasses [ owl:members ( fis:LockProduct fis:OptionProduct ) ] .

fis:Forward rdfs:subClassOf fis:LockProduct ;
    rdfs:comment "A non-standardized, over-the-counter contract between two parties to buy or sell an asset at a specified future time at a price agreed today." .
fis:Future rdfs:subClassOf fis:LockProduct ;
    rdfs:comment "A standardized contract written by a clearing house that operates an exchange where the contract can be bought and sold." .
fis:Swap rdfs:subClassOf fis:LockProduct ;
    rdfs:comment "Two counterparties exchange cash flows of one party's financial instrument for those of the other's." .
fis:Option rdfs:subClassOf fis:OptionProduct ;
    rdfs:comment "Gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future fis:Swap fis:Option ) ] .

fis:Warrant rdfs:subClassOf fis:Option ;
    rdfs:comment "A long-dated option, generally traded over the counter." .

fis:EquityWarrant owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Warrant
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
    rdfs:comment "Issued by a company, allowing the holder to purchase a specific number of shares at a specified price within a specified time." .
fis:EquityWarrant rdfs:subClassOf fis:HybridSecurity .

fis:CallOption owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasRight ; owl:someValuesFrom fis:RightToBuy ] ) ] .
fis:PutOption owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasRight ; owl:someValuesFrom fis:RightToSell ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanStyleOption owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:someValuesFrom fis:AmericanExerciseStyle ] ) ] .
fis:EuropeanStyleOption owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:someValuesFrom fis:EuropeanExerciseStyle ] ) ] .
fis:BermudanStyleOption owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:someValuesFrom fis:BermudanExerciseStyle ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:AmericanStyleOption fis:EuropeanStyleOption fis:BermudanStyleOption ) ] .

fis:AsianOption rdfs:subClassOf fis:Option ;
    rdfs:comment "Payoff determined by the average underlying price over some preset time period." .
fis:BarrierOption rdfs:subClassOf fis:Option ;
    rdfs:comment "The underlying security's price must pass a certain barrier before it can be exercised." .
fis:BinaryOption rdfs:subClassOf fis:Option ;
    rdfs:comment "An all-or-nothing option that pays the full amount if the underlying meets a defined condition at expiration." .
fis:ExoticOption rdfs:subClassOf fis:Option ;
    rdfs:comment "Any option with complex financial structures beyond the vanilla American/European forms." .

fis:InterestRateSwap rdfs:subClassOf fis:Swap .
fis:CurrencySwap rdfs:subClassOf fis:Swap .
fis:CreditDefaultSwap owl:equivalentClass
    [ a owl:Class ; owl:intersectionOf ( fis:Swap
        [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:DebtSecurity ] ) ] ;
    rdfs:label "CDS" ;
    rdfs:comment "The seller compensates the buyer in the event of a loan default or other credit event on the reference entity." .

owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap ) ] .

#################################################################
# ACCOUNTING CLASSIFICATION (IAS 32 / IFRS 9) — LIGHTWEIGHT OVERLAY
#################################################################

fis:FinancialAsset rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:comment "IAS 32: cash, an equity instrument of another entity, a contractual right to receive cash or another financial asset, or a contractual right to exchange financial instruments under potentially favourable conditions. This measurement-oriented classification cuts across the market taxonomy of debt/equity/derivative." .

fis:FinancialLiability rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:comment "IAS 32: a contractual obligation to deliver cash or another financial asset, or to exchange financial instruments under potentially unfavourable conditions. The same compound instrument (e.g. a convertible bond) may be split into a FinancialLiability component and an equity component." .

fis:AmortizedCostAsset rdfs:subClassOf fis:FinancialAsset ;
    rdfs:comment "IFRS 9: held in a hold-to-collect business model and passes the solely-payments-of-principal-and-interest (SPPI) test." .
fis:FVOCIAsset rdfs:subClassOf fis:FinancialAsset ;
    rdfs:label "fair value through other comprehensive income asset" ;
    rdfs:comment "IFRS 9: held in a hold-to-collect-and-sell business model and passes the SPPI test." .
fis:FVTPLAsset rdfs:subClassOf fis:FinancialAsset ;
    rdfs:label "fair value through profit or loss asset" ;
    rdfs:comment "IFRS 9: all financial assets not qualifying for amortised cost or FVOCI, including all derivative financial assets and (by default) equity investments." .

owl:AllDisjointClasses [ owl:members ( fis:AmortizedCostAsset fis:FVOCIAsset fis:FVTPLAsset ) ] .
